INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG04_TVET_009', 'TVET', 'Visioning a sustainable future', 'Commitment to ethical leadership, transparency, and accountability in education governance.', 'Active'), ('CFV_SDG04_TVET_010', 'TVET', 'Visioning a sustainable future', 'Respect for equity, fairness, and the use of education as a means to reduce social and gender inequalities.', 'Active'), ('CFV_SDG04_TVET_011', 'TVET', 'Visioning a sustainable future', 'Openness to challenging biased norms and promoting dignity, inclusion, and participation for all learners.', 'Active'), ('CFV_SDG04_TVET_012', 'TVET', 'Visioning a sustainable future', 'Appreciation of STEM as a driver of sustainable development and willingness to adapt to innovation and change.', 'Active'), ('CFV_SDG04_TVET_013', 'TVET', 'Visioning a sustainable future', 'Respect for diverse knowledge systems, including Indigenous, cultural, and community-based learning traditions.', 'Active'), ('CFV_SDG04_TVET_014', 'TVET', 'Visioning a sustainable future', 'Belief in ECCE as a right and a foundation for social inclusion, holistic development, and lifelong learning.', 'Active'), ('CFV_SDG04_TER_001', 'Tertiary education', 'Appreciation of education as a human right', 'Uphold education as a right, not a privilege, and commit to advancing access for all, particularly underserved populations.', 'Active'), ('CFV_SDG04_TER_002', 'Tertiary education', 'Appreciation of education as a human right', 'Recognise the interdependence of education with other human rights, such as health, equality and participation.', 'Active'), ('CFV_SDG04_TER_003', 'Tertiary education', 'Inclusivity and social justice', 'Promote inclusive, equitable education that embraces diversity of identity, culture, language and ability.', 'Active'), ('CFV_SDG04_TER_004', 'Tertiary education', 'Inclusivity and social justice', 'Challenge all forms of discrimination and exclusion within and beyond educational settings.', 'Active'), ('CFV_SDG04_TER_005', 'Tertiary education', 'Commitment to nation building and global citizenship', 'Value education’s role in shaping responsible, engaged citizens for national cohesion and sustainable development.', 'Active'), ('CFV_SDG04_TER_006', 'Tertiary education', 'Commitment to nation building and global citizenship', 'Embrace education’s potential to build peace, justice and social solidarity locally and globally.', 'Active'), ('CFV_SDG04_TER_007', 'Tertiary education', 'Professional integrity and empowerment', 'Embody ethical leadership in education with a focus on community empowerment, especially for women and marginalised groups.', 'Active'), ('CFV_SDG04_TER_008', 'Tertiary education', 'Professional integrity and empowerment', 'Value and support ecce as a transformative field that benefits both learners and their caregivers.', 'Active'), ('CFV_SDG04_TER_009', 'Tertiary education', 'Respect for knowledge diversity', 'Value different systems of knowledge, including scientific, indigenous, experiential and informal learning.', 'Active'), ('CFV_SDG04_TER_010', 'Tertiary education', 'Respect for knowledge diversity', 'Appreciate the relevance of traditional and local knowledge in addressing global and local sustainability challenges.', 'Active'), ('CFV_SDG04_ADULT_001', 'Adult education', 'Valuing education at all ages', 'Appreciate the value of education for personal growth, empowerment and improved quality of life – at any age or stage.', 'Active'), ('CFV_SDG04_ADULT_002', 'Adult education', 'Valuing education at all ages', 'Recognise education as a lifelong journey and embrace continuous learning for employment, social connection, leisure and active citizenship.', 'Active'), ('CFV_SDG04_ADULT_003', 'Adult education', 'Parental and community engagement', 'Encourage and support children’s schooling and learning through active involvement at home and in school life.', 'Active'), ('CFV_SDG04_ADULT_004', 'Adult education', 'Parental and community engagement', 'Value the role of families and communities in creating a culture of education, care and opportunity.', 'Active'), ('CFV_SDG04_ADULT_005', 'Adult education', 'Empowerment and self-worth', 'Develop a strong sense of self-worth and agency to pursue personal learning goals and life improvements.', 'Active'), ('CFV_SDG04_ADULT_006', 'Adult education', 'Empowerment and self-worth', 'Build confidence in one’s ability to learn, grow and contribute meaningfully to the household and community.', 'Active'), ('CFV_SDG04_ADULT_007', 'Adult education', 'Inclusion and social responsibility', 'Commit to equitable access to education and the inclusion of all learners regardless of gender, literacy level, disability, or life experience.', 'Active'), ('CFV_SDG04_ADULT_008', 'Adult education', 'Inclusion and social responsibility', 'Show solidarity with others in learning and collective problem solving to build stronger, more resilient communities.', 'Active'), ('CFV_SDG05_SEC_001', 'Secondary education', 'Promoting respect, equality and inclusion', 'Demonstrate respect for all individuals regardless of gender identity, expression or roles and uphold gender equality as a fundamental human right.', 'Active'), ('CFV_SDG05_SEC_002', 'Secondary education', 'Promoting respect, equality and inclusion', 'Advocate for inclusive school environments where diversity is valued and all learners feel safe, respected and represented.', 'Active'), ('CFV_SDG05_SEC_003', 'Secondary education', 'Promoting respect, equality and inclusion', 'Encourage peers to explore activities and careers traditionally dominated by the opposite gender, supporting freedom of choice and personal expression.', 'Active'), ('CFV_SDG05_SEC_004', 'Secondary education', 'Promoting respect, equality and inclusion', 'Actively challenge stereotypes and discriminatory attitudes in classroom interactions, media content and social settings.', 'Active'), ('CFV_SDG05_SEC_005', 'Secondary education', 'Promoting respect, equality and inclusion', 'Promote emotional literacy by supporting the expression of diverse emotions across all genders and dismantling stereotypes about how boys and girls should behave or feel.', 'Active'), ('CFV_SDG05_SEC_006', 'Secondary education', 'Challenging gender-based violence and discrimination', 'Show commitment to ending gender-based violence (GBV) by promoting non-violence, equality and safe relationships.', 'Active'), ('CFV_SDG05_SEC_007', 'Secondary education', 'Challenging gender-based violence and discrimination', 'Design and lead education campaigns, peer mediation programmes or community outreach initiatives to raise awareness of GBV and offer support to those affected.', 'Active'), ('CFV_SDG05_SEC_008', 'Secondary education', 'Challenging gender-based violence and discrimination', 'Critically assess and advocate for the improvement of laws and policies protecting individuals from GBV and gender discrimination at the local, national and global levels.', 'Active'), ('CFV_SDG05_SEC_009', 'Secondary education', 'Challenging gender-based violence and discrimination', 'Respect and support the enforcement of regional and global agreements such as the Convention on the Elimination of All Forms of Discrimination Against Women (CEDAW).', 'Active'), ('CFV_SDG05_SEC_010', 'Secondary education', 'Critical reflection and collective action', 'Recognise and speak out against unjust gender norms and cultural practices, such as child marriage or unequal educational opportunities, especially when they harm girls and women.', 'Active'), ('CFV_SDG05_SEC_011', 'Secondary education', 'Critical reflection and collective action', 'Value and promote diverse gender perspectives by collaborating on school and community initiatives that celebrate and protect gender rights.', 'Active'), ('CFV_SDG05_SEC_012', 'Secondary education', 'Critical reflection and collective action', 'Develop media literacy by examining how stereotypes and gender roles are constructed across platforms and create content (for example, podcasts, posters, blogs) that challenge biases and promote fairness.', 'Active'), ('CFV_SDG05_SEC_013', 'Secondary education', 'Critical reflection and collective action', 'Acknowledge how intersectionality (race, class, disability, sexual orientation) shapes gendered experiences and actively support inclusive, anti-discriminatory practices.', 'Active'), ('CFV_SDG05_SEC_014', 'Secondary education', 'Global solidarity and cultural sensitivity', 'Understand and respect cultural diversity while promoting universal values of fairness and equality.', 'Active'), ('CFV_SDG05_SEC_015', 'Secondary education', 'Global solidarity and cultural sensitivity', 'Engage with stories and experiences from different parts of the world to understand how gender inequality is experienced and addressed globally, especially in Commonwealth countries.', 'Active'), ('CFV_SDG05_SEC_016', 'Secondary education', 'Global solidarity and cultural sensitivity', 'Promote inclusive global citizenship by supporting international efforts to uphold women’s and girls’ rights and by participating in cross-cultural dialogues on gender justice.', 'Active'), ('CFV_SDG05_SEC_017', 'Secondary education', 'Global solidarity and cultural sensitivity', 'Be an engaged global citizen by advocating for gender equality and working towards solutions that ensure equality worldwide.', 'Active'), ('CFV_SDG05_SEC_018', 'Secondary education', 'Global solidarity and cultural sensitivity', 'Promote the importance of SDG5 and encourage others to participate in initiatives that support global gender equality.', 'Active'), ('CFV_SDG05_TVET_001', 'TVET', 'Promoting equity, inclusion and respect', 'Demonstrate empathy and understanding of the barriers faced by women and gender minorities in education and employment.', 'Active'), ('CFV_SDG05_TVET_002', 'TVET', 'Promoting equity, inclusion and respect', 'Advocate for inclusive policies that ensure equal access to training, mentorship and job opportunities.', 'Active'), ('CFV_SDG05_TVET_003', 'TVET', 'Promoting equity, inclusion and respect', 'Support flexible and family-friendly workplace arrangements that accommodate diverse needs.', 'Active'), ('CFV_SDG05_TVET_004', 'TVET', 'Promoting equity, inclusion and respect', 'Encourage enrolment of girls and women in non-traditional fields and promote gender-neutral career guidance.', 'Active'), ('CFV_SDG05_TVET_005', 'TVET', 'Promoting equity, inclusion and respect', 'Acknowledge and challenge personal and institutional biases that impact gender equity.', 'Active'), ('CFV_SDG05_TVET_006', 'TVET', 'Leadership, empowerment and accountability', 'Lead or contribute to initiatives that improve gender representation in technical sectors.', 'Active'), ('CFV_SDG05_TVET_007', 'TVET', 'Leadership, empowerment and accountability', 'Support peer mentoring, leadership training and advocacy networks for women in TVET and the workforce.', 'Active'), ('CFV_SDG05_TVET_008', 'TVET', 'Leadership, empowerment and accountability', 'Encourage inclusive leadership practices and fair decision-making processes in educational and workplace settings.', 'Active') ON CONFLICT DO NOTHING;